package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseM3MigrationTest extends MigrationTestSupport {
 @Test void populatedM2RetainsActivityMembershipAndAnonymousAudiences(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_m3_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("48").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));
  try{UUID owner=db.queryForObject("INSERT INTO users(email,password_hash,status,email_verified) VALUES('m3-legacy@example.test','synthetic-only','ACTIVE',TRUE) RETURNING id",UUID.class),g=UUID.randomUUID(),event=UUID.randomUUID();db.update("INSERT INTO communities(id,name,slug,privacy_type,created_by) VALUES(?,'Historical M3 hidden','g-legacy-m3','HIDDEN',?)",g,owner);db.update("INSERT INTO community_members(community_id,user_id,role,rules_version_ack) VALUES(?,?,'OWNER',1)",g,owner);db.update("INSERT INTO community_events(id,community_id,host_user_id,title,starts_at,ends_at) VALUES(?,?,?,'Preserved circle',CURRENT_TIMESTAMP+INTERVAL '1 day',CURRENT_TIMESTAMP+INTERVAL '2 days')",event,g,owner);db.update("INSERT INTO community_event_attendees(event_id,user_id) VALUES(?,?)",event,owner);db.update("INSERT INTO posts(author_id,community_id,body,is_anonymous,visibility) VALUES(?,?,'Preserved anonymous discussion',TRUE,'COMMUNITY')",owner,g);var before=db.queryForList("SELECT id,author_id,is_anonymous,visibility,body,community_id FROM posts");var f=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load();f.migrate();f.validate();assertThat(db.queryForList("SELECT id,author_id,is_anonymous,visibility,body,community_id FROM posts")).isEqualTo(before);assertThat(db.queryForObject("SELECT count(*) FROM community_event_attendees WHERE event_id=?",Integer.class,event)).isEqualTo(1);assertThat(db.queryForObject("SELECT revision FROM community_events WHERE id=?",Long.class,event)).isEqualTo(1);assertThat(db.queryForObject("SELECT privacy_type FROM communities WHERE id=?",String.class,g)).isEqualTo("HIDDEN");assertThat(db.queryForObject("SELECT count(*) FROM community_content_actions",Integer.class)).isZero();
  }finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}
 }
}
